func scratchCapture(fn func()) string {
	var buf bytes.Buffer

	orig := logger
	logger = log.New(&buf, "", 0)

	defer func() { logger = orig }()

	fn()

	return buf.String()
}

func scratchSetEnv(key, mode, okFile string) {
	_ = os.Unsetenv(key)
	_ = os.Unsetenv(key + "_FILE")

	switch mode {
	case "<unset>":
	case "<file-missing>":
		_ = os.Setenv(key+"_FILE", "/nonexistent/scratch/"+key)
	case "<file-ok>":
		_ = os.Setenv(key+"_FILE", okFile)
	default:
		_ = os.Setenv(key, mode)
	}
}

func scratchIsolateEnv(t *testing.T, keys []string) {
	t.Helper()

	envBackup := backupEnvironmentVariables()

	t.Cleanup(func() {
		for _, k := range keys {
			_ = os.Unsetenv(k)
			_ = os.Unsetenv(k + "_FILE")
		}

		restoreEnvironmentVariables(envBackup)
	})
}

func sortedLines(s string) []string {
	l := strings.Split(s, "\n")
	sort.Strings(l)

	return l
}

