func TestScratchDiffCheckProviders(t *testing.T) {
	var keys []string

	providers := make([]string, 0, len(enabledProviderAuth))

	for p, params := range enabledProviderAuth {
		providers = append(providers, p)
		keys = append(keys, params...)
	}

	sort.Strings(providers)
	sort.Strings(keys)
	scratchIsolateEnv(t, keys)

	okFile := filepath.Join(t.TempDir(), "ok")
	require.NoError(t, os.WriteFile(okFile, []byte("tok\n"), 0o600))

	pool := []string{"<unset>", "<unset>", "<unset>", "", " ", "x", "x", "<file-missing>", "<file-ok>"}

	r := rand.New(rand.NewSource(2))

	var okCount, errCount int

	for i := 0; i < 6000; i++ {
		for _, k := range keys {
			scratchSetEnv(k, pool[r.Intn(len(pool))], okFile)
		}

		for _, p := range providers {
			var (
				wantN, gotN     int
				wantErr, gotErr error
			)

			wantLog := scratchCapture(func() { wantN, wantErr = oldCheckProvider(p) })
			gotLog := scratchCapture(func() { gotN, gotErr = checkProvider(p) })

			require.Equal(t, wantN, gotN, "checkProvider(%s) count, iteration %d", p, i)
			require.Equal(t, wantLog, gotLog, "checkProvider(%s) log, iteration %d", p, i)
			require.Equal(t, wantErr == nil, gotErr == nil, "checkProvider(%s) err nil-ness, iteration %d", p, i)

			if wantErr != nil {
				require.Equal(t, wantErr.Error(), gotErr.Error())
			}
		}

		var wantErr, gotErr error

		wantLog := scratchCapture(func() { wantErr = oldCheckProvidersDefined() })
		gotLog := scratchCapture(func() { gotErr = checkProvidersDefined() })

		require.Equal(t, wantErr == nil, gotErr == nil, "checkProvidersDefined err nil-ness, iteration %d: base=%v head=%v", i, wantErr, gotErr)
		require.Equal(t, sortedLines(wantLog), sortedLines(gotLog), "checkProvidersDefined log lines, iteration %d", i)

		if wantErr != nil {
			errCount++

			require.Equal(t, sortedLines(wantErr.Error()), sortedLines(gotErr.Error()), "iteration %d", i)
		} else {
			okCount++
		}
	}

	t.Logf("checkProviders: 6000 random env configurations identical (ok=%d err=%d)", okCount, errCount)
}

